B.aei=new A.r([B.m,"Costo: 300 Shard o una carica gratis.",B.k,"Coste: 300 Shards o una carga gratis.",B.i,"\u30b3\u30b9\u30c8\uff1a300\u30b7\u30e3\u30fc\u30c9\u307e\u305f\u306f\u7121\u6599\u30c1\u30e3\u30fc\u30b81\u56de\u3002",B.h,"\ube44\uc6a9: \uc0e4\ub4dc 300\uac1c \ub610\ub294 \ubb34\ub8cc \ucda9\uc804 1\ud68c.",B.f,"\u82b1\u8d39\uff1a300\u788e\u7247\u6216\u4e00\u6b21\u514d\u8d39\u5145\u80fd\u3002",B.j,"Kosten: 300 Shards oder eine Gratisladung."],t.N)
