B.abD=new A.r([B.m,"Email per il reset della password inviata.",B.k,"Correo para restablecer la contrase\xf1a enviado.",B.i,"\u30d1\u30b9\u30ef\u30fc\u30c9\u518d\u8a2d\u5b9a\u30e1\u30fc\u30eb\u3092\u9001\u4fe1\u3057\u307e\u3057\u305f\u3002",B.h,"\ube44\ubc00\ubc88\ud638 \uc7ac\uc124\uc815 \uc774\uba54\uc77c\uc744 \ubcf4\ub0c8\uc2b5\ub2c8\ub2e4.",B.f,"\u5bc6\u7801\u91cd\u7f6e\u90ae\u4ef6\u5df2\u53d1\u9001\u3002",B.j,"E-Mail zum Zur\xfccksetzen des Passworts gesendet."],t.N)
B.af3=new A.r([B.m,"Cloud non disponibile. I progressi locali sono al sicuro.",B.k,"Nube no disponible. El progreso local est\xe1 seguro.",B.i,"\u30af\u30e9\u30a6\u30c9\u3092\u5229\u7528\u3067\u304d\u307e\u305b\u3093\u3002\u30ed\u30fc\u30ab\u30eb\u306e\u9032\u884c\u72b6\u6cc1\u306f\u5b89\u5168\u3067\u3059\u3002",B.h,"\ud074\ub77c\uc6b0\ub4dc\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ub85c\uceec \uc9c4\ud589 \uc0c1\ud669\uc740 \uc548\uc804\ud569\ub2c8\ub2e4.",B.f,"\u4e91\u7aef\u4e0d\u53ef\u7528\u3002\u672c\u5730\u8fdb\u5ea6\u5b89\u5168\u65e0\u635f\u3002",B.j,"Cloud nicht verf\xfcgbar. Lokaler Fortschritt ist sicher."],t.N)
B.ae4=new A.r([B.m,"Nessun backup cloud disponibile.",B.k,"No hay copia en la nube disponible.",B.i,"\u5229\u7528\u53ef\u80fd\u306a\u30af\u30e9\u30a6\u30c9\u30d0\u30c3\u30af\u30a2\u30c3\u30d7\u304c\u3042\u308a\u307e\u305b\u3093\u3002",B.h,"\uc0ac\uc6a9 \uac00\ub2a5\ud55c \ud074\ub77c\uc6b0\ub4dc \ubc31\uc5c5\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.",B.f,"\u6ca1\u6709\u53ef\u7528\u7684\u4e91\u7aef\u5907\u4efd\u3002",B.j,"Kein Cloud-Backup verf\xfcgbar."],t.N)
B.af2=new A.r([B.m,"Account diverso su questo dispositivo. Scegli i progressi locali o cloud.",B.k,"Hay otra cuenta en este dispositivo. Elige el progreso local o en la nube.",B.i,"\u3053\u306e\u7aef\u672b\u3067\u306f\u5225\u306e\u30a2\u30ab\u30a6\u30f3\u30c8\u304c\u4f7f\u308f\u308c\u3066\u3044\u307e\u3059\u3002\u4fdd\u6301\u3059\u308b\u9032\u884c\u72b6\u6cc1\u3092\u9078\u629e\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc774 \uae30\uae30\uc5d0 \ub2e4\ub978 \uacc4\uc815\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc720\uc9c0\ud560 \uc9c4\ud589 \uc0c1\ud669\uc744 \uc120\ud0dd\ud558\uc138\uc694.",B.f,"\u6b64\u8bbe\u5907\u4e0a\u6709\u5176\u4ed6\u8d26\u6237\u3002\u8bf7\u9009\u62e9\u8981\u4fdd\u7559\u7684\u8fdb\u5ea6\u3002",B.j,"Anderes Konto auf diesem Ger\xe4t. Lokalen oder Cloud-Fortschritt w\xe4hlen."],t.N)
B.aej=new A.r([B.m,"Nessun salvataggio cloud per questo account. Controlla prima di importare il dispositivo.",B.k,"No hay partida en la nube para esta cuenta. Rev\xedsala antes de importar este dispositivo.",B.i,"\u3053\u306e\u30a2\u30ab\u30a6\u30f3\u30c8\u306b\u30af\u30e9\u30a6\u30c9\u30bb\u30fc\u30d6\u304c\u3042\u308a\u307e\u305b\u3093\u3002\u7aef\u672b\u3092\u53d6\u308a\u8fbc\u3080\u524d\u306b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc774 \uacc4\uc815\uc5d0 \ud074\ub77c\uc6b0\ub4dc \uc800\uc7a5\uc774 \uc5c6\uc2b5\ub2c8\ub2e4. \uae30\uae30\ub97c \uac00\uc838\uc624\uae30 \uc804\uc5d0 \ud655\uc778\ud558\uc138\uc694.",B.f,"\u6b64\u8d26\u6237\u6ca1\u6709\u4e91\u7aef\u5b58\u6863\u3002\u5bfc\u5165\u6b64\u8bbe\u5907\u524d\u8bf7\u68c0\u67e5\u3002",B.j,"Kein Cloud-Spielstand f\xfcr dieses Konto. Vor dem Import pr\xfcfen."],t.N)
B.aeo=new A.r([B.m,"Trovati progressi cloud pi\xf9 recenti. Controlla prima di sostituire quelli del dispositivo.",B.k,"Se encontr\xf3 progreso m\xe1s reciente en la nube. Rev\xedsalo antes de reemplazar el del dispositivo.",B.i,"\u3088\u308a\u65b0\u3057\u3044\u30af\u30e9\u30a6\u30c9\u9032\u884c\u72b6\u6cc1\u304c\u898b\u3064\u304b\u308a\u307e\u3057\u305f\u3002\u7f6e\u304d\u63db\u3048\u308b\u524d\u306b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\ub354 \ucd5c\uc2e0 \ud074\ub77c\uc6b0\ub4dc \uc9c4\ud589 \uc0c1\ud669\uc744 \ucc3e\uc558\uc2b5\ub2c8\ub2e4. \uad50\uccb4\ud558\uae30 \uc804\uc5d0 \ud655\uc778\ud558\uc138\uc694.",B.f,"\u53d1\u73b0\u66f4\u65b0\u7684\u4e91\u7aef\u8fdb\u5ea6\u3002\u66ff\u6362\u524d\u8bf7\u68c0\u67e5\u3002",B.j,"Neuerer Cloud-Fortschritt gefunden. Vor dem Ersetzen pr\xfcfen."],t.N)
